<?php $regionList = $entity === 'regions'; $label = $regionList ? 'Wilayah' : 'Makanan'; ?>
<div class="admin-heading"><div><h1><?= $e($title) ?></h1><p><?= $regionList ? 'Kelola daerah dan cerita kuliner yang menyertainya.' : 'Lengkapi katalog makanan agar ceritanya bisa dikenal lebih luas.' ?></p></div><a class="button button-primary button-small" href="<?= $e($ui->url($entity . '.create')) ?>"><?= $ui->icon('plus') ?> Tambah <?= $label ?></a></div>
<?php if ($items): ?>
<div class="table-panel"><div class="table-scroller" role="region" aria-label="Tabel <?= $e($title) ?>, geser untuk melihat semua kolom" tabindex="0"><table><thead><tr><th scope="col"><?= $regionList ? 'Kabupaten/Kota' : 'Makanan' ?></th><?php if ($regionList): ?><th scope="col">Deskripsi</th><?php else: ?><th scope="col">Asal Daerah</th><th scope="col">Kategori</th><?php endif; ?><th scope="col">Aksi</th></tr></thead><tbody>
<?php foreach ($items as $item): ?><tr><td><div class="table-name"><?php if (!$regionList): ?><img class="table-thumbnail" src="<?= $e($ui->photo($item['photo'] ?? null)) ?>" alt="" width="48" height="48" loading="lazy" data-image-fallback="<?= $e($ui->asset('images/food-placeholder.svg')) ?>"><?php else: ?><?= $ui->icon('pin') ?><?php endif; ?><span><?= $e($item['name']) ?></span></div></td><?php if ($regionList): ?><td><p class="table-description"><?= $e($item['description'] ?: 'Deskripsi belum ditambahkan.') ?></p></td><?php else: ?><td><?= $e($ui->regionName($item['region_id'] ?? null)) ?></td><td><span class="category-tag"><?= $e($item['category']) ?></span></td><?php endif; ?><td><div class="row-actions"><a class="icon-button" href="<?= $e($ui->url($entity . '.edit', ['id' => $item['id']])) ?>" aria-label="Edit <?= $e($item['name']) ?>" title="Edit"><?= $ui->icon('edit') ?></a><form action="<?= $e($ui->url($entity . '.destroy', ['id' => $item['id']])) ?>" method="post" data-delete-form data-delete-name="<?= $e($item['name']) ?>" <?= !$ui->options['connected'] ? 'data-preview-form' : '' ?>><?= $ui->csrf() ?><input type="hidden" name="_method" value="DELETE"><button type="submit" class="icon-button delete-button" aria-label="Hapus <?= $e($item['name']) ?>" title="Hapus"><?= $ui->icon('trash') ?></button><p class="form-feedback" role="status" tabindex="-1"></p></form></div></td></tr><?php endforeach; ?>
</tbody></table></div><p class="table-note"><?= count($items) ?> data ditampilkan<?= $ui->options['adminPreview'] ? ' · data referensi/pratinjau, belum terhubung ke penyimpanan' : '' ?>.</p></div>
<?php else: ?>
<div class="empty-state"><span class="empty-icon"><?= $ui->icon($regionList ? 'pin' : 'food') ?></span><h3>Belum ada <?= strtolower($label) ?>.</h3><p>Tambahkan data pertama untuk mulai melengkapi informasi SiKuliner Riau.</p><a class="button button-outline button-small" href="<?= $e($ui->url($entity . '.create')) ?>">Tambah <?= $label ?><?= $ui->icon('plus') ?></a></div>
<?php endif; ?>
